func:
// 入口校验。参数不合法时回 400/422 且不写投递日志：
// 没有可信 notifyId 做主键，强写会产生无主记录（接口规范 §4.4）。
function reject(m, code, text) {
    m.statusCode = code;
    m.payload = { error: text };
    return [m, null];
}

let body = msg.payload;
if (typeof body === "string") {
    try {
        body = JSON.parse(body);
    } catch (e) {
        return reject(msg, 400, "请求体不是合法 JSON");
    }
}
if (body === null || typeof body !== "object" || Array.isArray(body)) {
    return reject(msg, 400, "请求体必须是 JSON 对象");
}

const missing = [];
for (const k of ["notifyId", "terminalId", "pointId", "alarmType"]) {
    if (typeof body[k] !== "string" || body[k].trim() === "") {
        missing.push(k);
    }
}
if (!Number.isInteger(body.level) || body.level < 1 || body.level > 4) {
    missing.push("level(1~4)");
}
if (typeof body.triggerValue !== "number" || !isFinite(body.triggerValue)) {
    missing.push("triggerValue");
}
if (!Number.isInteger(body.occurTime) || body.occurTime <= 0) {
    missing.push("occurTime(毫秒)");
}
if (missing.length > 0) {
    return reject(msg, 422, "缺少或非法字段：" + missing.join(", "));
}

msg.notify = body;
msg.params = [body.notifyId, body.terminalId, body.pointId, body.alarmType, body.occurTime];
msg.payload = null;
return [null, msg];

// 一次查询同时回答两件事：这个 notifyId 是否已推送过、卡片需要的配置域字段是什么。
// 已推送过的请求直接丢弃，防重复推送（接口规范 §9.2 通知级幂等）。
// 只把 SENT 当重复：上次失败的那条允许重来，靠 ON CONFLICT 覆盖同一行。
const rows = msg.payload;
if (!Array.isArray(rows) || rows.length === 0) {
    msg.statusCode = 422;
    msg.payload = { error: "未知测点：" + msg.notify.terminalId + " / " + msg.notify.pointId };
    return [msg, null];
}
const row = rows[0];
if (row.duplicate) {
    msg.statusCode = 200;
    msg.payload = { notifyId: msg.notify.notifyId, status: "DUPLICATE" };
    return [msg, null];
}
msg.meta = row;
return [null, msg];

// 组装卡片（BR-40）：车间、终端、测点、级别、触发值、发生时间、告警原因。
// 车间与测点名称取自配置域投影，请求里只有标识。
const LEVEL_TEXT = { 1: "提示", 2: "警告", 3: "严重", 4: "紧急" };
const TYPE_TEXT = {
    HIGH_LIMIT: "高限", HIGH_HIGH_LIMIT: "高高限", LOW_LIMIT: "低限",
    STATE_ALARM: "状态报警", SENSOR_OFFLINE: "传感器离线", TERMINAL_OFFLINE: "终端离线",
    CACHE_WARNING: "缓存预警", DATA_QUALITY_ERROR: "数据质量异常"
};

function pad(v) {
    return String(v).padStart(2, "0");
}
function fmt(ms) {
    const d = new Date(ms);   // 容器 TZ=Asia/Shanghai，与面板时区一致
    return d.getFullYear() + "-" + pad(d.getMonth() + 1) + "-" + pad(d.getDate()) +
        " " + pad(d.getHours()) + ":" + pad(d.getMinutes()) + ":" + pad(d.getSeconds());
}

const n = msg.notify;
const m = msg.meta;
const levelText = LEVEL_TEXT[n.level] || String(n.level);
const alarmTypeText = TYPE_TEXT[n.alarmType] || n.alarmType;
const deviceText = m.device_name + " · 总线" + m.bus_id + " · 从站" + m.slave_addr;
// 告警标识回查不到时留空：adapter 先落库再发通知，回查不到说明告警已被清理，
// 卡片照样发，只是少一个交叉索引。
const alarmId = m.alarm_id ? "AL-" + String(m.alarm_id).padStart(7, "0") : null;
const unitText = m.unit ? " " + m.unit : "";

const lines = [
    "**【" + levelText + "】" + m.point_name + alarmTypeText + "**",
    "> 车间：" + m.workshop,
    "> 终端：" + n.terminalId,
    "> 设备：" + deviceText,
    "> 触发值：**" + n.triggerValue + unitText + "**",
    "> 采集时间：" + fmt(n.occurTime)
];
if (n.reason) {
    lines.push("> 原因：" + n.reason);
}

msg.card = {
    notifyId: n.notifyId,
    channel: env.get("NOTIFY_CHANNEL") || "wecom-mock",
    msgtype: "markdown",
    alarm: {
        alarmId: alarmId,
        level: n.level,
        levelText: levelText,
        workshop: m.workshop,
        terminalId: n.terminalId,
        deviceText: deviceText,
        pointText: m.point_name,
        alarmType: n.alarmType,
        alarmTypeText: alarmTypeText,
        triggerValue: n.triggerValue,
        unit: m.unit || null,
        occurTime: n.occurTime,
        reason: n.reason || null,
        backfill: false
    },
    markdown: { content: lines.join("\n") }
};

// level 1 只入库不发通知（BR-39）。
return n.level <= 1 ? [msg, null] : [null, msg];

// 受理应答走一条分支，投递走另一条。响应一旦发出就与投递结果无关，
// 接入服务只发不等结果（详细设计 §4.2）。
const n = msg.notify;
const resp = {
    _msgid: msg._msgid,
    res: msg.res,
    statusCode: 200,
    payload: { notifyId: n.notifyId, status: "SKIPPED" }
};
const work = { _msgid: msg._msgid, notify: n, meta: msg.meta };
work.logEntry = { status: "SKIPPED", retryCount: 0, httpCode: null, failReason: "level=1 仅入库，不投递" };
return [resp, work];

const n = msg.notify;
const resp = {
    _msgid: msg._msgid,
    res: msg.res,
    statusCode: 202,
    payload: { notifyId: n.notifyId, status: "ACCEPTED" }
};
const work = { _msgid: msg._msgid, notify: n, meta: msg.meta, card: msg.card };
return [resp, work];

// 参数顺序与「写投递日志」节点里的 SQL 一一对应。
// 成功与失败都写同一行：同一 notifyId 只有一条留痕，重复投递靠 ON CONFLICT 覆盖。
const n = msg.notify;
const e = msg.logEntry || {};
msg.params = [
    n.notifyId,
    (msg.meta && msg.meta.alarm_id) || null,
    env.get("NOTIFY_CHANNEL") || "wecom-mock",
    e.status,
    e.retryCount || 0,
    (e.httpCode === undefined || e.httpCode === null) ? null : e.httpCode,
    e.failReason || null
];
return msg;

// 投递从这一刻起与 HTTP 响应无关：响应已经在另一条分支发走了。
msg.url = env.get("WECOM_WEBHOOK_URL") || "";
msg.headers = { "Content-Type": "application/json" };
msg.payload = msg.card;
msg.attempt = 1;
// 单次投递上半 5 秒：通道挂死时重试阶梯不能被一次请求无限期拖住。
msg.requestTimeout = 5000;
// 重试间隔：首次立即，之后 1s / 5s / 15s，共 4 次（BR-41）。
msg.retryDelaysMs = [1000, 5000, 15000];
return msg;

const code = Number(msg.statusCode);
if (Number.isFinite(code) && code >= 200 && code < 300) {
    msg.logEntry = { status: "SENT", retryCount: msg.attempt - 1, httpCode: code };
    return [msg, null];
}
msg.lastHttpCode = Number.isInteger(code) ? code : null;
return [null, msg];

// 首次 + NOTIFY_MAX_RETRY 次重试（默认 3，与 AGENTS.md 的通知重试表一致）。
// 间隔表用完后沿用最后一个间隔，避免第 4 次以后变成零间隔风暴。
const maxRetries = Number(env.get("NOTIFY_MAX_RETRY") || 3);
const maxAttempts = Math.max(1, maxRetries) + 1;
if (msg.attempt < maxAttempts) {
    const idx = Math.min(msg.attempt - 1, msg.retryDelaysMs.length - 1);
    msg.delay = msg.retryDelaysMs[idx];
    msg.attempt += 1;
    return [msg, null];
}
msg.logEntry = {
    status: "FAILED",
    retryCount: msg.attempt - 1,
    httpCode: msg.lastHttpCode === undefined ? null : msg.lastHttpCode,
    failReason: String(msg.payload).slice(0, 500)
};
return [null, msg];

// 统一异常出口，分两种。
//
// 一、写投递日志失败：按 1 秒重试 3 次。日志是这条通知的唯一留痕，
//     丢了就查不出「发出去了没有」。响应早已发出，重试不拖慢调用方。
// 二、其余异常（查询失败、函数抛错）：没有可信 notifyId 就没有留痕，
//     回 500 让调用方从自己日志里看到，不写库、不重试。
const err = msg.error || {};
const sourceId = (err.source && err.source.id) || "";
const detail = err.message ? err.message : String(err);
const isLogWrite = sourceId === "f1a0000000000017";
// 投递失败已经由重试阶梯处理并有失败日志，这里再刷一条只是噪音。
const isDelivery = sourceId === "f1a0000000000022";
if (isDelivery) {
    return [null, null];
}

if (isLogWrite) {
    const tried = (msg.logRetry || 0) + 1;
    if (tried <= 3) {
        msg.logRetry = tried;
        msg.delay = 1000;
        return [null, msg];
    }
    node.error("写投递日志连续失败 3 次，已放弃：" + detail);
    return [null, null];
}

node.warn("通知流程异常：" + detail);
if (!msg.res || !msg.notify) {
    return [null, null];
}
msg.statusCode = 500;
msg.payload = { error: "通知触达层内部错误", detail: detail };
return [msg, null];
